using System;using System.Linq;using System.Collections.Generic;using System.ComponentModel;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using System.Windows.Automation;using Gunt.ControlCenter.Infrastructure;using Gunt.ControlCenter.Models;
namespace Gunt.ControlCenter.Views {
 public sealed partial class MainWindow {
  readonly Button discard=new Button{Content="변경 버리기"},undo=new Button{Content="직전 적용 취소"};readonly TextBlock pending=new TextBlock{Margin=new Thickness(0,0,12,8),VerticalAlignment=VerticalAlignment.Center};bool selecting,allowClose;
  void SetupFooter(DockPanel panel){foreach(var b in new[]{discard,undo}){DockPanel.SetDock(b,Dock.Right);panel.Children.Add(b);}DockPanel.SetDock(pending,Dock.Right);panel.Children.Add(pending);discard.Click+=delegate{if(vm.Fields.Any(f=>f.IsDirty)&&Decide("변경 버리기","저장하지 않은 변경만 버릴까요? 실제 설정은 변경하지 않습니다.","변경 버리기","계속 편집")==0){foreach(var f in vm.Fields)f.Discard();vm.Status="미저장 변경을 버렸습니다.";UpdateDirty();}};undo.Click+=delegate{Run(()=>vm.Service.Undo(),()=>Show(page));};}
  void HookFields(){foreach(var f in vm.Fields)f.PropertyChanged+=delegate{if(Dispatcher.CheckAccess())UpdateDirty();else Dispatcher.BeginInvoke((Action)UpdateDirty);};UpdateDirty();}
  void UpdateDirty(){int n=vm.Fields.Count(f=>f.IsDirty);pending.Text=n>0?"미저장 변경 "+n+"개":"저장된 상태";pending.Foreground=n>0?Accent:Muted;apply.IsEnabled=!busy&&n>0;discard.IsEnabled=!busy&&n>0;undo.IsEnabled=!busy&&n==0&&vm.Service.CanUndo;apply.Visibility=n>0?Visibility.Visible:Visibility.Collapsed;discard.Visibility=apply.Visibility;pending.Visibility=n>0?Visibility.Visible:Visibility.Collapsed;undo.Visibility=vm.Service.CanUndo?Visibility.Visible:Visibility.Collapsed;}
  int Decide(string title,string explanation,params string[] choices){int answer=choices.Length-1;var w=new Window{Title=title,Owner=this,Width=580,SizeToContent=SizeToContent.Height,MaxHeight=Math.Max(300,ActualHeight-50),Background=Surface,Foreground=TextColor,FontFamily=FontFamily,FontSize=14,WindowStartupLocation=WindowStartupLocation.CenterOwner,ResizeMode=ResizeMode.NoResize};w.Resources.MergedDictionaries.Add(UxTheme.Resources);var stack=new StackPanel{Margin=new Thickness(20)};var scroll=new ScrollViewer{Content=new TextBlock{Text=explanation,TextWrapping=TextWrapping.Wrap},MaxHeight=340,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};stack.Children.Add(scroll);var buttons=new WrapPanel{Margin=new Thickness(0,20,0,0)};for(int i=0;i<choices.Length;i++){int value=i;var b=new Button{Content=choices[i],Padding=new Thickness(12,8,12,8),Margin=new Thickness(0,0,8,0),Background=Secondary,Foreground=TextColor,BorderBrush=Line,IsCancel=i==choices.Length-1};b.Click+=delegate{answer=value;w.DialogResult=true;};buttons.Children.Add(b);}stack.Children.Add(buttons);w.Content=stack;w.ShowDialog();return answer;}
  void RestoreNavSelection(){selecting=true;navigation.SelectedItem=navigation.Items.Cast<ListBoxItem>().FirstOrDefault(x=>Convert.ToString(x.Tag)==page);selecting=false;}
  void Navigate(string target){if(target==page)return;if(busy){RestoreNavSelection();return;}if(WaitForDeveloperSelection(()=>SelectPage(target))){RestoreNavSelection();return;}if(!ConfirmSessionDraft()){RestoreNavSelection();return;}if(vm.Fields.Any(f=>f.IsDirty)){string summary;try{summary=vm.Service.Summary(vm.Fields);}catch(Exception e){summary="입력 확인 필요: "+e.Message;}int choice=Decide("미저장 설정","이 페이지에 저장하지 않은 변경이 있습니다.\n\n"+summary,"적용하고 이동","버리고 이동","계속 편집");if(choice==2){RestoreNavSelection();return;}if(choice==0){ApplyPending(()=>Show(target),false);return;}}Show(target);}
  void ApplyPending(Action next,bool preview){if(busy)return;try{string summary=vm.Service.Summary(vm.Fields);if(summary.Length==0)return;var fields=vm.Fields.ToArray();if(preview&&(fields.Count(f=>f.IsDirty)>1||fields.Any(f=>f.IsDirty&&(f.Config=="dock"||f.Config=="startup"))))if(Decide("적용할 설정",summary,"설정 적용","취소")!=0)return;Run(()=>vm.Service.Apply(fields),()=>{UpdateDirty();if(next!=null)next();});}catch(Exception e){vm.Status="입력을 확인하세요: "+e.Message;RestoreNavSelection();}}
  void ProtectClose(object sender,CancelEventArgs e){if(allowClose)return;if(busy){e.Cancel=true;vm.Status="작업이 끝난 뒤 창을 닫을 수 있습니다.";return;}if(WaitForDeveloperSelection(()=>Close())){e.Cancel=true;return;}if(!ConfirmSessionDraft()){e.Cancel=true;return;}if(!vm.Fields.Any(f=>f.IsDirty))return;int choice=Decide("미저장 설정","저장하지 않은 변경이 있습니다. 창을 닫기 전에 어떻게 할까요?","적용하고 닫기","버리고 닫기","계속 편집");if(choice==2)e.Cancel=true;else if(choice==0){e.Cancel=true;ApplyPending(()=>{allowClose=true;Close();},false);}}
  string ChoiceLabel(SettingField field,string value){if(field.Key=="graphHistorySeconds")return value+"초";if(field.Key=="updateMs")return (Int32.Parse(value)/1000)+"초";if(value=="dynamic")return "동적 축";if(value=="fixed")return "고정 축";if(value=="auto")return "자동";if(value=="manual")return "수동 위치";if(value=="none"||value=="Disabled")return "사용 안 함";return value;}
  string paletteShortcut="Ctrl+K";
  void RefreshPaletteShortcut(){try{paletteShortcut=Gunt.ControlCenter.Services.DesktopService.S(vm.Service.Optional("ux"),"commandPaletteShortcut","Ctrl+K");}catch(Exception error){vm.Status="단축키 설정 확인 필요: "+error.Message;}}
  void UxKeyDown(object sender,KeyEventArgs e){string hotkey=paletteShortcut;if(Keyboard.Modifiers==ModifierKeys.Control&&e.Key==Key.S){e.Handled=true;if(page=="development-sessions"&&sessionDraft!=null)SaveSessionDraft();else ApplyPending(null,true);}else if((hotkey=="Ctrl+K"&&Keyboard.Modifiers==ModifierKeys.Control&&e.Key==Key.K)||(hotkey=="Ctrl+Shift+P"&&Keyboard.Modifiers==(ModifierKeys.Control|ModifierKeys.Shift)&&e.Key==Key.P)){e.Handled=true;OpenCommandPalette();}}
 }
}
